ALTER TABLE "User" ADD COLUMN "phoneEncrypted" TEXT, ADD COLUMN "phoneHash" TEXT UNIQUE, ADD COLUMN "phoneVerifiedAt" TIMESTAMPTZ(3), ADD COLUMN "contactRequired" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN purpose TEXT CHECK (purpose IN ('PLAYER','HOST')), ADD COLUMN "onboardingCompletedAt" TIMESTAMPTZ(3), ADD COLUMN "sportsPreferences" TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN "areaPreferences" TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN "timePreferences" TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN "goalPreferences" TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN "courtPreference" TEXT NOT NULL DEFAULT 'No preference', ADD COLUMN "budgetMin" INTEGER, ADD COLUMN "budgetMax" INTEGER, ADD COLUMN "recommendationsEnabled" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "AccountToken" ADD COLUMN "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "AccountToken" ADD COLUMN "subjectHash" TEXT;
CREATE TABLE "VerificationChallenge" (id UUID PRIMARY KEY, "userId" UUID NOT NULL REFERENCES "User"(id), "phoneHash" TEXT NOT NULL, "ipHash" TEXT NOT NULL, "codeHash" TEXT NOT NULL, "localCipher" TEXT, attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5), "deliveryState" TEXT NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMPTZ(3) NOT NULL, "usedAt" TIMESTAMPTZ(3));
CREATE INDEX ON "VerificationChallenge"("userId","createdAt"); CREATE INDEX ON "VerificationChallenge"("phoneHash","createdAt"); CREATE INDEX ON "VerificationChallenge"("ipHash","createdAt");
CREATE TABLE "FacilityDraft" (id UUID PRIMARY KEY, "userId" UUID NOT NULL REFERENCES "User"(id), data JSONB NOT NULL DEFAULT '{}', relationship TEXT NOT NULL DEFAULT 'OWNER' CHECK(relationship IN ('OWNER','MANAGER','REPRESENTATIVE')), "idType" TEXT, stage TEXT NOT NULL DEFAULT 'DRAFT' CHECK(stage IN ('DRAFT','SUBMITTED')), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ON "FacilityDraft"("userId","updatedAt");
CREATE TABLE "VerificationDocument" (id UUID PRIMARY KEY,"draftId" UUID NOT NULL REFERENCES "FacilityDraft"(id),kind TEXT NOT NULL CHECK(kind IN ('IDENTITY','SUPPORT','PHOTO')),"encryptedContent" TEXT, bytes INTEGER NOT NULL CHECK(bytes>0 AND bytes<=8388608),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMPTZ(3) NOT NULL,"deletedAt" TIMESTAMPTZ(3));
CREATE INDEX ON "VerificationDocument"("draftId",kind);
ALTER TABLE "FacilityApplication" DROP CONSTRAINT "FacilityApplication_state_check";
ALTER TABLE "FacilityApplication" ADD CONSTRAINT "FacilityApplication_state_check" CHECK(state IN ('PENDING','UNDER_REVIEW','CLARIFICATION','APPROVED','REJECTED','SUSPENDED'));
ALTER TABLE "FacilityApplication" ADD COLUMN "draftId" UUID UNIQUE REFERENCES "FacilityDraft"(id), ADD COLUMN "reviewerId" UUID REFERENCES "User"(id), ADD COLUMN "identityState" TEXT NOT NULL DEFAULT 'NOT_SUBMITTED', ADD COLUMN "facilityState" TEXT NOT NULL DEFAULT 'NOT_REVIEWED';
ALTER TABLE "AdminDecision" ADD COLUMN "previousState" TEXT, ADD COLUMN "newState" TEXT;
CREATE TABLE "StaffInvitation" (id UUID PRIMARY KEY,"facilityId" UUID NOT NULL REFERENCES "Facility"(id),"invitedBy" UUID NOT NULL REFERENCES "User"(id),email TEXT NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,permissions TEXT[] NOT NULL,state TEXT NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','ACCEPTED','REVOKED')),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMPTZ(3) NOT NULL,"acceptedBy" UUID REFERENCES "User"(id));
CREATE INDEX ON "StaffInvitation"("facilityId",state);
GRANT SELECT,INSERT,UPDATE,DELETE ON "VerificationChallenge","FacilityDraft","VerificationDocument","StaffInvitation" TO larosentry_app;
